using AutoMapper; using Health_Care_System.BLL.Interfaces; using Health_Care_System.PL.ViewModels; using Health_Care_System.Entities; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.Rendering;
namespace Health_Care_System.PL.Controllers;
[Authorize] public class AppointmentsController:Controller { private const int PageSize=10; private readonly IAppointmentService _service; private readonly IUnitOfWork _uow; private readonly IMapper _mapper; public AppointmentsController(IAppointmentService service,IUnitOfWork uow,IMapper mapper){_service=service;_uow=uow;_mapper=mapper;} private async Task LoadLists(){ViewBag.Patients=new SelectList(await _uow.Patients.GetAllAsync(),"Id","Name");ViewBag.Doctors=new SelectList(await _uow.Doctors.GetAllAsync(),"Id","Name");} public async Task<IActionResult> Index(string? searchValue,int pageIndex=1){var r=await _service.GetAllAsync(searchValue,pageIndex,PageSize);if(!r.Successeded||r.Data is null)return Problem(r.Error);ViewBag.SearchValue=searchValue;return View(r.Data);} [HttpGet] public async Task<IActionResult> Create(){await LoadLists();return View();} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(AppointmentViewModel model){if(!ModelState.IsValid){await LoadLists();return View(model);}var r=await _service.CreateAsync(_mapper.Map<Appointment>(model));if(!r.Successeded){ModelState.AddModelError("",r.Error!);await LoadLists();return View(model);}return RedirectToAction(nameof(Index));} public async Task<IActionResult> Details(int patientId,int doctorId){var r=await _service.GetByIdAsync(patientId,doctorId);if(!r.Successeded||r.Data is null)return NotFound();return View(_mapper.Map<AppointmentViewModel>(r.Data));} [HttpGet] public async Task<IActionResult> Edit(int patientId,int doctorId){var r=await _service.GetByIdAsync(patientId,doctorId);if(!r.Successeded||r.Data is null)return NotFound();await LoadLists();return View(_mapper.Map<AppointmentViewModel>(r.Data));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(AppointmentViewModel model){if(!ModelState.IsValid){await LoadLists();return View(model);}var r=await _service.UpdateAsync(_mapper.Map<Appointment>(model));if(!r.Successeded){ModelState.AddModelError("",r.Error!);await LoadLists();return View(model);}return RedirectToAction(nameof(Index));} public async Task<IActionResult> Delete(int patientId,int doctorId){var r=await _service.GetByIdAsync(patientId,doctorId);if(!r.Successeded||r.Data is null)return NotFound();return View(_mapper.Map<AppointmentViewModel>(r.Data));} [HttpPost,ActionName("Delete"),ValidateAntiForgeryToken] public async Task<IActionResult> ConfirmDelete(int patientId,int doctorId){var r=await _service.DeleteAsync(patientId,doctorId);if(!r.Successeded)return NotFound();return RedirectToAction(nameof(Index));} }
